import{_ as l,W as i,s as o,u as d,ah as u,I as t,w as a,Z as e,A as p}from"./chunks/framework.DPWZnL3N.js";import"./chunks/theme.DZmP8ALZ.js";const v=JSON.parse('{"title":"使用 du 检查 Linux 上已用的磁盘空间 | LCTT x X-CMD","titleTemplate":false,"description":"使用 du 检查 Linux 上已用的磁盘空间 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"使用 du 检查 Linux 上已用的磁盘空间 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 du 检查 Linux 上已用的磁盘空间 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210727 Check used disk space on Linux with du","title":"使用 du 检查 Linux 上已用的磁盘空间","tag":"202108"},"relativePath":"202108/20210727 Check used disk space on Linux with du.md","filePath":"[post].md"}'),r={name:"202108/20210727 Check used disk space on Linux with du.md"};function c(h,s,m,g,b,x){const n=i("Link");return d(),o("div",null,[s[18]||(s[18]=u(`<h1 id="使用-du-检查-linux-上已用的磁盘空间" tabindex="-1">使用 du 检查 Linux 上已用的磁盘空间 <a class="header-anchor" href="#使用-du-检查-linux-上已用的磁盘空间" aria-label="Permalink to 使用 du 检查 Linux 上已用的磁盘空间">​</a></h1><blockquote><p>用 Linux 的 du 命令了解你正在使用多少磁盘空间。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/06/200731j561cwxyxyekaic5.jpg" alt=""></p><p>无论你有多少存储空间，它总有可能被填满。在大多数个人设备上，磁盘被照片、视频和音乐填满，但在服务器上，由于用户账户和日志文件数据，空间减少是很正常的。无论你是负责管理一个多用户系统，还是只负责自己的笔记本电脑，你都可以用 <code>du</code> 命令检查磁盘的使用情况。</p><p>默认情况下，<code>du</code> 列出了当前目录中使用的磁盘空间，以及每个子目录的大小。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ du</span></span>
<span class="line"><span>12 ./.backups</span></span>
<span class="line"><span>60 .</span></span></code></pre></div><p>在这个例子中，当前目录总共占用了 60KB，其中 12KB 被子目录 <code>.backups</code> 占用。</p><p>如果你觉得这很混乱，并希望分别看到所有的大小，你可以使用 <code>--separate-dirs</code>（或简写 <code>-S</code>）选项：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ du --separate-dirs</span></span>
<span class="line"><span>12 ./.backups</span></span>
<span class="line"><span>48 .</span></span></code></pre></div><p>显示相同的信息（48KB 加 12KB 是 60KB），但每个目录被独立处理。</p><p>如需看到更多的细节，可以使用 <code>--all</code>（简写 <code>-a</code>）选项，它显示每个目录中以及每个文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ du --separate-dirs --all        </span></span>
<span class="line"><span>4    ./example.adoc</span></span>
<span class="line"><span>28   ./graphic.png</span></span>
<span class="line"><span>4    ./.backups/example.adoc~</span></span>
<span class="line"><span>12   ./.backups</span></span>
<span class="line"><span>4    ./index.html</span></span>
<span class="line"><span>4    ./index.adoc</span></span>
<span class="line"><span>48   .</span></span></code></pre></div><h3 id="查看文件的修改时间" tabindex="-1">查看文件的修改时间 <a class="header-anchor" href="#查看文件的修改时间" aria-label="Permalink to 查看文件的修改时间">​</a></h3><p>当查看文件以找出占用空间的内容时，查看文件最后一次被修改的时间是很有用的。一年内没有使用过的文件可以考虑归档，特别是当你的空间快用完时。</p><p>通过 <code>du</code> 查看文件的修改时间，使用 <code>--time</code> 选项：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ du --separate-dirs --all --time</span></span>
<span class="line"><span>28   2021-07-21 11:12    ./graphic.png</span></span>
<span class="line"><span>4    2021-07-03 10:43    ./example.adoc</span></span>
<span class="line"><span>4    2021-07-13 13:03    ./index.html</span></span>
<span class="line"><span>4    2021-07-23 14:18    ./index.adoc</span></span>
<span class="line"><span>48   2021-07-23 14:19    .</span></span></code></pre></div><h3 id="为文件大小设置一个阈值" tabindex="-1">为文件大小设置一个阈值 <a class="header-anchor" href="#为文件大小设置一个阈值" aria-label="Permalink to 为文件大小设置一个阈值">​</a></h3><p>当为了磁盘空间而查看文件时，你可能只关心较大的文件。你可以通过 <code>--threshold</code>（简写 <code>-t</code>）选项为文件大小设置一个阈值。例如，只查看大于 1GB 的文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ \\du --separate-dirs --all --time --threshold=1G ~/Footage/</span></span>
<span class="line"><span>1839008 2021-07-14 13:55    /home/tux/Footage/snowfall.mp4</span></span>
<span class="line"><span>1577980 2020-04-11 13:10    /home/tux/Footage/waterfall.mp4</span></span>
<span class="line"><span>8588936 2021-07-14 13:55    /home/tux/Footage/</span></span></code></pre></div><p>当文件较大时，它们可能难以阅读。使用 <code>--human-readable</code>（简写 <code>-h</code>）选项可以使文件大小更容易阅读：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ du --separate-dirs --all --time --threshold=1G --human-readable ~/Footage/</span></span>
<span class="line"><span>1.8G 2021-07-14 13:55    /home/tux/Footage/snowfall.mp4</span></span>
<span class="line"><span>1.6G 2020-04-11 13:10    /home/tux/Footage/waterfall.mp4</span></span>
<span class="line"><span>8.5G 2021-07-14 13:55    /home/tux/Footage/</span></span></code></pre></div><h3 id="查看可用磁盘空间" tabindex="-1">查看可用磁盘空间 <a class="header-anchor" href="#查看可用磁盘空间" aria-label="Permalink to 查看可用磁盘空间">​</a></h3>`,22)),t("p",null,[s[1]||(s[1]=a("如需获得一个驱动器上可用磁盘空间的摘要，请阅读我们关于 ")),e(n,{href:"https://opensource.com/article/21/7/use-df-check-free-disk-space-linux"},{default:p(()=>s[0]||(s[0]=[a("df 命令")])),_:1}),s[2]||(s[2]=a("的文章。"))]),s[19]||(s[19]=t("hr",null,null,-1)),t("p",null,[s[4]||(s[4]=a("via: ")),e(n,{href:"https://opensource.com/article/21/7/check-disk-space-linux-du"},{default:p(()=>s[3]||(s[3]=[a("https://opensource.com/article/21/7/check-disk-space-linux-du")])),_:1})]),t("p",null,[s[9]||(s[9]=a("作者：")),e(n,{href:"https://opensource.com/users/seth"},{default:p(()=>s[5]||(s[5]=[a("Seth Kenlon")])),_:1}),s[10]||(s[10]=a(" 选题：")),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>s[6]||(s[6]=[a("lujun9972")])),_:1}),s[11]||(s[11]=a(" 译者：")),e(n,{href:"https://github.com/geekpi"},{default:p(()=>s[7]||(s[7]=[a("geekpi")])),_:1}),s[12]||(s[12]=a(" 校对：")),e(n,{href:"https://github.com/turbokernel"},{default:p(()=>s[8]||(s[8]=[a("turbokernel")])),_:1})]),t("p",null,[s[15]||(s[15]=a("本文由 ")),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>s[13]||(s[13]=[a("LCTT")])),_:1}),s[16]||(s[16]=a(" 原创编译，")),e(n,{href:"https://linux.cn/"},{default:p(()=>s[14]||(s[14]=[a("Linux中国")])),_:1}),s[17]||(s[17]=a(" 荣誉推出"))])])}const C=l(r,[["render",c]]);export{v as __pageData,C as default};
